def prepare_factorial():
    fact = [1]
    for i in range(1, 200005):
        fact.append((fact[-1] * i) % MOD)
    ifact = [0] * 200005
    ifact[200004] = pow(fact[200004], MOD - 2, MOD)
    for i in range(200004, 0, -1):
        ifact[i - 1] = (i * ifact[i]) % MOD
    return fact, ifact

